changeSet.sql:
INSERT INTO pep_category (country_iso, code, label, kind, risk_class, sort_order, legal_reference)
VALUES ('EE', 'EE-EU', 'Estoniens exerçant une fonction européenne', 'EU', 1, 10, 'Liste de la Commission, JO C/2023/724');

INSERT INTO pep_function (category_id, label, institution, expected_holders)
SELECT c.id, f.label, f.institution, f.expected_holders
FROM pep_category c JOIN (
    SELECT 'EE-EU' AS code, 'Député européen élu en Estonie' AS label, 'Parlement européen' AS institution, 7 AS expected_holders
    UNION ALL SELECT 'EE-EU', 'Membre estonien de la Commission européenne', 'Commission européenne', 1
) f ON f.code = c.code;

